/* @lc app=leetcode id=3640 lang=kotlin */ class Solution { fun maxSumTrionic(nums: IntArray): Long = nums.indices.drop(1).fold(listOf(-1_000_000_000_000_000_000L, -1_000_000_000_000_000_000L, -1_000_000_000_000_000_000L, -1_000_000_000_000_000_000L)) { (a, b, c, best), i -> nums[i].toLong().let { x -> nums[i - 1].toLong().let { y -> (if (x > y) x + maxOf(a, y) else -1_000_000_000_000_000_000L).let { na -> (if (x < y) x + maxOf(b, a) else -1_000_000_000_000_000_000L).let { nb -> (if (x > y) x + maxOf(c, b) else -1_000_000_000_000_000_000L).let { nc -> listOf(na, nb, nc, maxOf(best, nc)) } } } } } }[3] }